// Everything about the policy's context that shifts its rates, as opposed to
// the items being priced. Travels as one value because every policy-wide
// modifier reads from it.
interface PolicyContext {
  customer: Customer;
  isFollowUpContract: boolean;
}

const policyWideModifierRatesFor = ({
  customer,
  isFollowUpContract,
}: PolicyContext): number[] => [
  FIRST_INSURANCE_SURCHARGE,
  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
];

const withPolicyWideModifiers = (
  policyBase: number,
  policy: PolicyContext,
): number =>
  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));

const quotePremium = (
  { items }: QuoteStep,
  policy: PolicyContext,
): number =>
  roundUpInFavourOfMHPCO(
    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
      itemSurchargesOf(items) +
      PROCESSING_FEE,
  );

// A quote is a follow-up contract when the customer already took a quote
// earlier in the same scenario.
const followsAnEarlierQuote = (steps: Step[], index: number): boolean =>
  steps.slice(0, index).some((step) => step.op === "quote");

export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => ({
  results: steps.map((step, index) => ({
    premium: quotePremium(step, {
      customer,
      isFollowUpContract: followsAnEarlierQuote(steps, index),
    }),
  })),
});
